#include <bits/stdc++.h>
using namespace std;

using i64 = long long;

struct SegTree {
  int n;
  vector<array<int, 2>> tr;

  SegTree(int n = 0) : n(n), tr(n * 4 + 5, {0, 0}) {}

  void pull(int p) {
    tr[p][0] = tr[p << 1][0] ^ tr[p << 1 | 1][0];
    tr[p][1] = tr[p << 1][1] ^ tr[p << 1 | 1][1];
  }

  void build(int p, int l, int r, const vector<int>& val, const vector<int>& dep_node) {
    if (l == r) {
      tr[p][dep_node[l] & 1] = val[l];
      return;
    }
    int mid = (l + r) >> 1;
    build(p << 1, l, mid, val, dep_node);
    build(p << 1 | 1, mid + 1, r, val, dep_node);
    pull(p);
  }

  void update(int p, int l, int r, int pos, int parity, int val) {
    if (l == r) {
      tr[p][0] = tr[p][1] = 0;
      tr[p][parity] = val;
      return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(p << 1, l, mid, pos, parity, val);
    else update(p << 1 | 1, mid + 1, r, pos, parity, val);
    pull(p);
  }

  int query(int p, int l, int r, int ql, int qr, int parity) {
    if (ql <= l && r <= qr) return tr[p][parity];
    int mid = (l + r) >> 1;
    int ans = 0;
    if (ql <= mid) ans ^= query(p << 1, l, mid, ql, qr, parity);
    if (qr > mid) ans ^= query(p << 1 | 1, mid + 1, r, ql, qr, parity);
    return ans;
  }
};

void solve() {
  int n, q;
  cin >> n >> q;

  vector<int> a(n + 1);
  for (int i = 1; i <= n; i++) cin >> a[i];

  vector<vector<int>> g(n + 1);
  for (int i = 1; i < n; i++) {
    int u, v;
    cin >> u >> v;
    g[u].push_back(v);
    g[v].push_back(u);
  }

  vector<int> parent(n + 1), dep(n + 1), siz(n + 1), heavy(n + 1);
  auto dfs1 = [&](auto&& self, int u, int fa) -> void {
    parent[u] = fa;
    dep[u] = dep[fa] + 1;
    siz[u] = 1;
    for (int v : g[u]) {
      if (v == fa) continue;
      self(self, v, u);
      siz[u] += siz[v];
      if (siz[v] > siz[heavy[u]]) heavy[u] = v;
    }
  };

  vector<int> top(n + 1), id(n + 1), rid(n + 1);
  int timer = 0;
  auto dfs2 = [&](auto&& self, int u, int tp) -> void {
    top[u] = tp;
    id[u] = ++timer;
    rid[timer] = u;
    if (heavy[u]) self(self, heavy[u], tp);
    for (int v : g[u]) {
      if (v == parent[u] || v == heavy[u]) continue;
      self(self, v, v);
    }
  };

  dfs1(dfs1, 1, 0);
  dfs2(dfs2, 1, 1);

  vector<int> val(n + 1), dep_node(n + 1);
  for (int i = 1; i <= n; i++) {
    val[id[i]] = a[i];
    dep_node[id[i]] = dep[i];
  }

  SegTree seg(n);
  seg.build(1, 1, n, val, dep_node);

  auto query_path = [&](int u, int v, int parity) {
    int ans = 0;
    while (top[u] != top[v]) {
      if (dep[top[u]] < dep[top[v]]) swap(u, v);
      ans ^= seg.query(1, 1, n, id[top[u]], id[u], parity);
      u = parent[top[u]];
    }
    if (dep[u] > dep[v]) swap(u, v);
    ans ^= seg.query(1, 1, n, id[u], id[v], parity);
    return ans;
  };

  auto lca = [&](int u, int v) {
    while (top[u] != top[v]) {
      if (dep[top[u]] < dep[top[v]]) swap(u, v);
      u = parent[top[u]];
    }
    return dep[u] < dep[v] ? u : v;
  };

  while (q--) {
    int op, u, v, k;
    cin >> op >> u >> v;
    if (op == 1) {
      a[u] = v;
      seg.update(1, 1, n, id[u], dep[u] & 1, v);
    } else {
      cin >> k;
      int w = lca(u, v);
      int len = dep[u] + dep[v] - 2 * dep[w] + 1;
      if (len % 2 == 0) {
        cout << (query_path(u, v, 0) ^ query_path(u, v, 1)) << '\n';
      } else {
        cout << query_path(u, v, (dep[u] & 1) ^ 1) << '\n';
      }
    }
  }
}

int main() {
  cin.tie(0)->sync_with_stdio(0);
  solve();
  return 0;
}
